#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Bench characterisation of one Govee light, from the box to a filled-in
# record of what it speaks. Run on the Pi next to the light:
#
#   tools/characterise.sh H6167          # label = whatever you call the light
#
# Human steps are physical (power on, pair in the app, pick a colour). Every
# Bluetooth step is run for you through tools/govee_rig.py. Findings go to
# bench/<label>.env, frame logs to bench/<label>-*.jsonl, HCI captures to
# bench/<label>-*.btsnoop. Re-running keeps values already recorded.

TOOLS_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_DIR="$(dirname "$TOOLS_DIR")"
RIG="$TOOLS_DIR/govee_rig.py"
PYTHON="${PYTHON:-$HOME/rig/bin/python}"
BENCH_DIR="${BENCH_DIR:-$REPO_DIR/bench}"
BTMON_PID=""

# rig STAGE ARGS... runs the rig with a per-stage frame log and shows output.
rig() {
  local tag="$1"; shift
  printf '  %s$ govee_rig.py %s%s\n' "$DIM" "$*" "$RESET"
  "$PYTHON" "$RIG" --log "$BENCH_DIR/$LABEL-$tag.jsonl" "$@" 2>&1 | sed 's/^/    /' || true
}

# connected ARGS... runs a rig subcommand against the recorded light.
connected() {
  local tag="$1" sub="$2"; shift 2
  rig "$tag" "$sub" "$ADDRESS" --no-scan --model "$MODEL" "$@"
}

btmon_start() {
  local file="$BENCH_DIR/$LABEL-$1.btsnoop"
  if ! command -v btmon >/dev/null 2>&1; then
    warn "btmon not installed (apt install bluez); skipping HCI capture"
    SKIPPED+=("HCI capture $file")
    return
  fi
  sudo -n true 2>/dev/null || say "btmon needs sudo; you may be asked for your password."
  sudo btmon -w "$file" >/dev/null 2>&1 &
  BTMON_PID=$!
  sleep 1
  printf '  %s● recording%s HCI to %s\n' "$GREEN" "$RESET" "$file"
}

btmon_stop() {
  [[ -n "$BTMON_PID" ]] || return 0
  sudo kill -INT "$BTMON_PID" 2>/dev/null || true
  wait "$BTMON_PID" 2>/dev/null || true
  BTMON_PID=""
  printf '  %s■ capture stopped%s\n' "$GREEN" "$RESET"
}

# record KEY "Prompt" asks the human to type what the rig just printed.
record() { ask "$1" "$2" && write_env "$1" "${!1}"; }

run_wizard() {

TOTAL_STAGES=12

LABEL="${1:-}"
if [[ -z "$LABEL" ]]; then
  printf '  %sLabel for this light (e.g. H6167 or H6167-tv):%s ' "$BOLD" "$RESET"
  read -r LABEL
fi
LABEL="${LABEL//[^A-Za-z0-9_-]/_}"
mkdir -p "$BENCH_DIR"
ENV_FILE="$BENCH_DIR/$LABEL.env"
trap btmon_stop EXIT

banner "Characterise a Govee light: $LABEL"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pre-flight"
say "Checking the Pi has what the rig needs."
if [[ ! -x "$PYTHON" ]]; then
  warn "no Python at $PYTHON. Create it: python3 -m venv ~/rig && ~/rig/bin/pip install bleak"
  warn "or set PYTHON=/path/to/python and re-run."
  exit 1
fi
"$PYTHON" -c "import bleak" 2>/dev/null || { warn "bleak missing: $PYTHON -m pip install bleak"; exit 1; }
if command -v bluetoothctl >/dev/null 2>&1; then
  bluetoothctl power on >/dev/null 2>&1 || true
  say "adapter: $(bluetoothctl show 2>/dev/null | grep -E 'Powered|Name' | tr -s ' ' | paste -sd ' ')"
fi
command -v btmon >/dev/null 2>&1 || warn "btmon not found: HCI captures will be skipped"
say "Records go to $ENV_FILE"
warn "Close the Govee app on every phone nearby. The light takes one connection at a time."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Unbox and power on, do NOT pair yet"
step "Unbox the light, connect the controller and the power supply."
step "Switch it on. Most strips light up white or run a rainbow on first power."
warn "Do not open the Govee app yet. An unpaired light may still hand out its"
warn "pairing secret over Bluetooth; once the app binds it, that may close."
say "Give it about 20 seconds to start advertising."
pause "Powered on and lit?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Find it"
say "Scanning for Govee lights. Yours should be the strongest signal."
rig scan scan --seconds 10
step "Find your light in the table above (model from the name, highest RSSI)."
record ADDRESS "Bluetooth address (AA:BB:CC:DD:EE:FF):"
record ADV_NAME "Advertised name exactly as shown:"
record MODEL "Model from the name (e.g. H6167):"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Identity reads, before pairing"
say "Firmware, hardware version, power, brightness, mode, IC count, light count,"
say "and the pairing secret. All reads, nothing written."
connected identity send read raw aa 07 03 sleep 1 raw aa 40 sleep 1 raw aa 0f sleep 1 raw aa b1 00 sleep 1.5 --hold 2
step "From the RX lines above:"
record FIRMWARE "Firmware version (from the 'firmware' line, or 'none'):"
record HW_VERSION "Hardware version reply to aa 07 03 (hex after 'aa07', or 'none'):"
record IC_COUNT_REPLY "Reply to aa 40, IC/segment count (hex, or 'none'):"
record SECRET_REPLY "Reply to aa b1 (16 hex chars after 'aab101', or 'none'):"
record MODE_BEFORE "Mode line as decoded (e.g. 'colour (0x0B...)', 'scene', 'unknown (0x13)'):"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Does it take writes before pairing?"
say "Power, a brightness and a colour in the table's dialect, each read back."
connected prepair verify on bri 50 rgb 18 52 86 sleep 1 off
step "Look at the '=>' verdict lines."
record WRITES_BEFORE_PAIR "Accepted writes before pairing? (yes / no / partial, with a note):"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Pair in the Govee app, with a capture running"
say "An HCI capture will run while you pair, so the app's first frames are"
say "kept. If the light needs a secret, the app sends it here as 33 B2."
btmon_start pair
step "Open the Govee app, add the device, and finish pairing. Let it update"
step "firmware if it insists, and note the new version if it does."
step "Then set the colour to pure RED from the colour wheel."
pause "Paired, red, and the app shows it connected?"
btmon_stop
record FIRMWARE_AFTER_PAIR "Firmware after pairing (same, or the new version):"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Read back what the app set"
step "Close the Govee app fully (swipe it away) so the light is free."
pause "App closed?"
say "Reading the mode the app left behind: this names the colour sub-mode."
connected after-red status --hold 1
record SUBMODE_RED "Sub-mode in the mode reply after the app set red (e.g. 0x0B, 0x15, 0x0D, 0x02):"
record MODE_RED_RAW "Raw RX mode frame (the 'aa05...' hex):"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "White, scene and music from the app"
say "Three more app-set states, each read back, to see how white, scene and"
say "music appear in the mode reply. Close the app between each."
step "App: set a WHITE around 4000 K, then close the app."
pause "Done?"
connected after-white status
record MODE_WHITE_RAW "Raw RX mode frame for white (aa05... hex, or 'none'):"
step "App: pick the FIRST built-in scene, then close the app."
pause "Done?"
connected after-scene status
record MODE_SCENE_RAW "Raw RX mode frame for the scene (aa05... hex):"
step "App: turn on MUSIC mode, any style, then close the app."
pause "Done?"
connected after-music status
record MODE_MUSIC_RAW "Raw RX mode frame for music (aa05... hex):"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Active probe"
say "Now the integration's own write-and-echo probe, all three candidates."
if confirm "Run the active probe? It changes the colour briefly."; then
  connected active status --active --candidates 02,0D,15
  record ACTIVE_RESULT "Active probe 'detected' line (sub-mode or 'none echoed'):"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Colour write in each dialect, with segment read-back"
say "A distinctive colour in 0x02, 0x0B, 0x0D and 0x15, each followed by a"
say "mode read and an AA A5 segment page, which is where RGBIC firmware"
say "keeps the real RGB."
for sm in 02 0B 0D 15; do
  say "--- sub-mode 0x$sm ---"
  connected "rgb-$sm" verify on submode "$sm" rgb 18 52 86 raw aa a5 01 sleep 1.5
  step "Did the strip actually turn the dark blue (18,52,86)?"
  record "VISUAL_RGB_$sm" "0x$sm colour write: visible change? (yes / no / wrong colour):"
done

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Brightness scale, colour temperature and scene codes"
say "Brightness 100 then 200 tells 0-100 from 0-255 firmware. Then a white"
say "in the likely dialect and the legacy scene codes."
connected bri verify bri 100 sleep 1 bri 200 sleep 1 bri 50
record BRIGHTNESS_SCALE "Brightness scale (255 if 200 echoed, 100 if clamped/ignored, other):"
record CT_SUBMODE "Which sub-mode to try white in (0D or 15, from the stages above):"
connected ct verify submode "$CT_SUBMODE" ct 4300 sleep 1 ct 6700 sleep 1
record CT_RESULT "ct verdicts (echoed kelvin / differs / no reply):"
connected scenes verify scene 0 sleep 2 scene 1 sleep 2 scene 4 sleep 2 scene 5 sleep 2 scene 7 sleep 2 scene 8 sleep 2 scene 9 sleep 2 scene 15 sleep 2
step "Watch the strip through the scene list: which IDs changed the effect?"
record SCENES_ACCEPTED "Scene IDs that visibly ran (e.g. '0,1,4,5' or 'none'):"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Secret test (only if writes were ignored)"
if [[ "${WRITES_BEFORE_PAIR:-}" == no* ]] || confirm "Did any write stage above get NO REPLY or no visible change?"; then
  say "If the light needs its 8-byte secret, sending it first should unlock writes."
  say "Sources: the aa b1 reply from stage 4, or the 33 B2 frame in"
  say "$BENCH_DIR/$LABEL-pair.btsnoop (Wireshark filter: btatt.value[0:2] == 33:b2)."
  ask_secret SECRET_HEX "8 secret bytes as 16 hex chars (or Enter to skip):" || true
  if [[ -n "${SECRET_HEX:-}" ]]; then
    write_env SECRET_HEX "$SECRET_HEX"
    connected secret verify raw 33 b2 "$SECRET_HEX" sleep 0.5 on rgb 255 0 0
    record SECRET_UNLOCKS "Did writes work after 33 B2? (yes / no):"
  fi
else
  say "Writes worked without a secret; nothing to do here."
fi
connected restore send off >/dev/null

finish
say "Record: $ENV_FILE"
say "Frame logs and captures: $BENCH_DIR/$LABEL-*"
say "Next: add $MODEL to custom_components/govee_bluetooth/models.py with the"
say "sub-mode and scale found, and attach this record to the pull request."
}

run_wizard "$@"; exit
